use std::f64::consts::PI;

// ---------- 1. 定义一个统一接口（trait） ----------
trait Shape {
    fn name(&self) -> &str;
    fn area(&self) -> f64;

    // 带默认实现的方法，同样会进入 vtable
    fn describe(&self) {
        println!("{} 的面积是 {:.2}", self.name(), self.area());
    }
}

// ---------- 2. 为不同类型实现该接口 ----------
struct Circle {
    radius: f64,
}
impl Shape for Circle {
    fn name(&self) -> &str {
        "圆"
    }
    fn area(&self) -> f64 {
        PI * self.radius * self.radius
    }
}

struct Rectangle {
    width: f64,
    height: f64,
}
impl Shape for Rectangle {
    fn name(&self) -> &str {
        "矩形"
    }
    fn area(&self) -> f64 {
        self.width * self.height
    }
}

// ---------- 3. 动态分发：trait object 存入异构集合 ----------
fn total_area(shapes: &[Box<dyn Shape>]) -> f64 {
    // 迭代 Box<dyn Shape>，运行期通过 vtable 调用 area()
    shapes.iter().map(|s| s.area()).sum()
}

// ---------- 4. 对象安全：伴随 trait 与工厂方法 ----------
trait Animal {
    fn speak(&self) -> String;
}

trait AnimalFactory {
    // `where Self: Sized` 把该方法从 vtable 中剔除，
    // 既保持 trait 对象安全，又能在具体类型上调用
    fn create(name: &'static str) -> Box<dyn Animal>
    where
        Self: Sized;
}

struct Dog {
    name: &'static str,
}
impl Animal for Dog {
    fn speak(&self) -> String {
        format!("{}: 汪汪!", self.name)
    }
}
impl AnimalFactory for Dog {
    fn create(name: &'static str) -> Box<dyn Animal> {
        Box::new(Dog { name })
    }
}

fn main() {
    // 异构集合：同一个 Vec 里放不同具体类型
    let shapes: Vec<Box<dyn Shape>> = vec![
        Box::new(Circle { radius: 2.0 }),
        Box::new(Rectangle { width: 3.0, height: 4.0 }),
    ];

    for s in &shapes {
        s.describe(); // 动态分发
    }
    println!("总面积: {:.2}", total_area(&shapes));

    // 工厂函数 + trait object 列表
    let animals: Vec<Box<dyn Animal>> = vec![Dog::create("旺财"), Dog::create("小白")];
    for a in &animals {
        println!("{}", a.speak());
    }

    // 直接接收 &dyn Trait 的函数，通常由泛型函数传入 &Concrete 自动 coerce
    fn draw(shape: &dyn Shape) {
        println!("正在绘制: {}", shape.name());
    }
    draw(&Circle { radius: 1.0 });
    draw(&Rectangle { width: 1.0, height: 2.0 });
}

