trait Greeter {
    fn name(&self) -> &str;
    fn hello(&self) -> String {
        format!("你好，我是 {}", self.name())
    }
}
struct Alice;
impl Greeter for Alice {
    fn name(&self) -> &str { "Alice" }
}
struct Bob;
impl Greeter for Bob {
    fn name(&self) -> &str { "Bob" }
    fn hello(&self) -> String { "Yo!".to_string() }
}
fn main() {
    let people: Vec<Box<dyn Greeter>> = vec![Box::new(Alice), Box::new(Bob)];
    for p in &people {
        println!("{}", p.hello());
    }
}
